PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE brand (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE product (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    brand TEXT NOT NULL,
    article_name TEXT NOT NULL,
    product_name TEXT NOT NULL,
    note TEXT,
    category TEXT NOT NULL,
    image_filename TEXT,
    image_url TEXT,
    image_public_id TEXT,
    minimum_threshold INTEGER NOT NULL DEFAULT 5,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (brand, article_name)
);
CREATE TABLE size_stock (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER NOT NULL,
    size TEXT NOT NULL,
    quantity INTEGER NOT NULL DEFAULT 0
        CHECK (quantity >= 0),
    minimum_threshold INTEGER NOT NULL DEFAULT 0
        CHECK (minimum_threshold >= 0),

    FOREIGN KEY (product_id)
        REFERENCES product(id)
        ON DELETE CASCADE,

    UNIQUE (product_id, size)
);
CREATE TABLE stock_movement (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER NOT NULL,
    size_stock_id INTEGER,
    size TEXT NOT NULL,
    previous_quantity INTEGER NOT NULL,
    new_quantity INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (product_id)
        REFERENCES product(id)
        ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX ix_product_brand
ON product(brand);
CREATE INDEX ix_product_article
ON product(article_name);
CREATE INDEX ix_product_name
ON product(product_name);
CREATE INDEX ix_product_category
ON product(category);
CREATE INDEX ix_size_product
ON size_stock(product_id);
CREATE INDEX ix_size_value
ON size_stock(size);
CREATE INDEX ix_movement_product
ON stock_movement(product_id);
